import pandas as pd,numpy as np
df=pd.read_parquet('equation.parquet');d=np.array(df.iloc[0]['training_set'].tolist())
y=d[:,0];t=d[:,1];P=d[:,2]
names=[];cols=[]
for i in range(5):
 for j in range(5):
  if i+j<=4: names.append('t^%d P^%d'%(i,j));cols.append((t**i)*(P**j))
X=np.column_stack(cols)
c,*_=np.linalg.lstsq(X,y,rcond=None)
for n,v in zip(names,c): print('%-10s %.6g'%(n,v))
print('rms',np.sqrt(np.mean((X@c-y)**2)))
"
